#include "compositors/niri/niri_window_rules.h"

#include "compositors/niri/niri_config_files.h"

#include <cctype>
#include <charconv>

namespace compositors::niri {
  namespace {

    constexpr std::string_view kManagedHeader =
        "// Generated by Noctalia from Settings → Roundness. Edits here are overwritten.\n";
    constexpr std::string_view kKeyword = "geometry-corner-radius";

    [[nodiscard]] std::optional<int> parseCornerRadius(std::string_view text) {
      const std::string stripped = stripComments(text);
      const auto pos = stripped.find(kKeyword);
      if (pos == std::string::npos) {
        return std::nullopt;
      }
      std::size_t i = pos + kKeyword.size();
      while (i < stripped.size() && (stripped[i] == ' ' || stripped[i] == '\t')) {
        ++i;
      }
      const std::size_t start = i;
      while (i < stripped.size() && (std::isdigit(static_cast<unsigned char>(stripped[i])) != 0)) {
        ++i;
      }
      if (i == start) {
        return std::nullopt;
      }
      int value = 0;
      const auto result = std::from_chars(stripped.data() + start, stripped.data() + i, value);
      if (result.ec != std::errc{}) {
        return std::nullopt;
      }
      return value;
    }

  } // namespace

  std::filesystem::path windowRulesIncludePath() { return includePath(kWindowRulesIncludeFileName); }

  std::string kdlForWindowCornerRadius(int radius) {
    std::string body(kManagedHeader);
    body += "window-rule {\n    geometry-corner-radius ";
    body += std::to_string(radius);
    body += "\n    clip-to-geometry true\n}\n";
    return body;
  }

  std::optional<int> currentWindowCornerRadius() { return currentWindowCornerRadiusFrom(configPath()); }

  std::optional<int> currentWindowCornerRadiusFrom(const std::filesystem::path& configFile) {
    const auto include = configFile.parent_path() / std::string(kWindowRulesIncludeFileName);
    const std::string text = readFile(include);
    if (text.empty()) {
      return std::nullopt;
    }
    return parseCornerRadius(text);
  }

  InstallResult saveWindowCornerRadius(int radius) { return saveWindowCornerRadiusInto(configPath(), radius); }

  InstallResult saveWindowCornerRadiusInto(const std::filesystem::path& configFile, int radius) {
    InstallResult result;
    if (configFile.empty()) {
      result.error = "niri config path is unknown";
      return result;
    }
    std::error_code ec;
    if (!std::filesystem::exists(configFile, ec) || ec) {
      result.error = "niri config not found";
      return result;
    }
    const auto include = configFile.parent_path() / std::string(kWindowRulesIncludeFileName);
    if (!writeFile(include, kdlForWindowCornerRadius(radius), result.error)) {
      return result;
    }
    if (!appendInclude(configFile, kWindowRulesIncludeFileName, result.error)) {
      return result;
    }
    result.ok = true;
    result.added = 1;
    return result;
  }

} // namespace compositors::niri
